/**
 * The reference to a file that an aggregate keeps, and all it keeps: the content lives in a
 * `FileStorage`, never in the database. It names no provider, no bucket and no URL, so the
 * connector can change without touching a row.
 */
export interface StoredFile {
  /** Generated by the server (`FileKeys`), never taken from the user. */
  readonly key: string;
  /** In bytes. */
  readonly size: number;
  /** Verified on the content, not only on the name the client gave. */
  readonly mediaType: string;
  /** `sha256:<hex>` of the content, computed while it streamed. */
  readonly checksum: string;
}
